-- HR Seeder
-- ================================================================
-- Demo data for the hr (people operations) module. Apply
-- supabase/examples/20260803000000_hr.sql first:
--
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 \
--     -f supabase/examples/20260803000000_hr.sql \
--     -f supabase/examples/h_seed.sql
--
-- Volume: 4 offices, 12 departments (three levels deep), 8 job
-- levels, 20 positions, 60 employees in a four-deep org chart with
-- compensation, documents and job history, 5 leave types with a
-- balance each, ~90 leave requests walked through approval, 24 public
-- holidays, ~380 timesheet entries, 2 review cycles with ~55 reviews
-- and ~70 cascading goals, 10 courses with ~85 enrollments, 8 job
-- openings with ~45 candidates and ~55 interviews, and the onboarding
-- checklist stamped onto every recent hire.
--
-- WHY THIS FILE WALKS ITS RECORDS
--
-- Leave balances, cycle progress and the headcount snapshot are all
-- derived. A leave request inserted as `approved` would move the
-- balance, but it would never exercise the overlap check, the
-- entitlement check or the self-approval guard — and the approval
-- queue, the notification and the decision timestamps would all be
-- missing. So leave is raised, then decided; timesheets are drafted,
-- then submitted, then approved; reviews move self-assessment ->
-- manager review -> shared -> acknowledged. What the dashboards show
-- is a consequence of those transitions, not of hand-written state.
--
-- Dates are relative to `current_date`, so the leave calendar, the
-- twelve-month headcount trend, the review gantt and the hiring plan
-- all have shape whenever this is run.
--
-- Five hardcoded users are seeded first (`on conflict do nothing`, so
-- this is safe alongside supabase/seed.sql and the other examples):
--   b73eb03e-fb7a-424d-84ff-18e2791ce0b8  superadmin@supasheet.app (x-admin)
--   b73eb03e-fb7a-424d-84ff-18e2791ce0c2  people@supasheet.app     (people_manager)
--   b73eb03e-fb7a-424d-84ff-18e2791ce0c3  talent@supasheet.app     (recruiter)
--   b73eb03e-fb7a-424d-84ff-18e2791ce0b4  user@supasheet.app       (user / employee)
--   b73eb03e-fb7a-424d-84ff-18e2791ce0b1  user1@supasheet.app      (user / employee)
--
-- Sign in as people@supasheet.app to see a LINE MANAGER's seat —
-- wired to Priya Raman, who has a real reporting tree, an approval
-- queue and reviews to write, and who can see her own people and
-- nobody else's. talent@supasheet.app is the recruiter: openings,
-- candidates and interviews, with no access to leave or pay.
-- user@supasheet.app is an ordinary employee (Grace Hopper): her own
-- record, her own leave and balances, the company directory, and
-- nothing more.
--
-- Password for every seeded user: the shared bcrypt hash below.
--
-- Not idempotent beyond the auth rows. Run `npx supabase db reset`
-- to start over.
-- ================================================================
----------------------------------------------------------------
