----------------------------------------------------------------
-- Employees
--
-- A four-deep org chart: one executive, five function leaders,
-- twelve managers and forty-two individual contributors. name,
-- tenure_months, probation_end_date and every headcount rollup are
-- derived by the triggers — this insert only states the facts.
--
-- Five of them are wired to a login. Priya Raman (people@) has a
-- real reporting tree, which is what makes the recursive
-- manager-scoped RLS visible in the UI.
----------------------------------------------------------------
insert into
  hr.employees (
    id,
    user_id,
    manager_id,
    department_id,
    location_id,
    position_id,
    level_id,
    first_name,
    last_name,
    work_email,
    personal_email,
    phone,
    employment_status,
    employment_type,
    work_mode,
    fte,
    hire_date,
    termination_date,
    termination_reason,
    nationality,
    emergency_contact_name,
    emergency_contact_phone,
    emergency_contact_relationship,
    skills,
    bio
  )
