----------------------------------------------------------------
-- Leave balances (annual and sickness for everyone still employed,
-- pro-rated for part-timers). taken, pending and remaining are all
-- derived — the requests below move them.
----------------------------------------------------------------
insert into
  hr.leave_balances (
    employee_id,
    leave_type_id,
    entitlement,
    carried_over
  )
select
  e.id,
  lt.id,
  case
    when e.fte < 100 then round((lt.default_allowance * e.fte / 100)::numeric, 1)
    else lt.default_allowance
  end,
  case
    when lt.code = 'AL'
    and e.hire_date < current_date - 365 then least(5, (abs(hashtext (e.id::text)) % 6))
    else 0
  end
from
  hr.employees e
  cross join hr.leave_types lt
where
  e.employment_status <> 'terminated'
  and lt.default_allowance > 0;

