-- Age the decision stamps onto the day they were actually made.
update hr.leave_requests
set
  submitted_at = (start_date - 21)::timestamptz + interval '9 hours',
  decided_at = case
    when decided_at is not null then (start_date - 19)::timestamptz + interval '11 hours'
  end,
  updated_at = (start_date - 19)::timestamptz + interval '11 hours';

----------------------------------------------------------------
-- Timesheets
--
-- The last three working weeks for the twenty people whose teams
-- track time. Drafted, then submitted, then approved by their
-- manager — never by themselves.
----------------------------------------------------------------
insert into
  hr.timesheet_entries (
    employee_id,
    work_date,
    hours_worked,
    overtime_hours,
    break_duration,
    project_code,
    task_note,
    is_billable,
    approver_id,
    status
  )
select
  e.id,
  d.day::date,
  case
    when extract(
      isodow
      from
        d.day
    ) = 5 then 7
    else 8
  end,
  case
    when (abs(hashtext (e.id::text || d.day::text)) % 9) = 0 then 1.5
    else 0
  end,
  2700000,
  (array['PLAT-1', 'APP-2', 'CS-3', 'INT-4']) [1 + (abs(hashtext (e.id::text)) % 4)],
  (
    array[
      'Feature work',
      'Bug fixing',
      'Customer call',
      'Planning',
      'Code review'
    ]
  ) [
    1 + (abs(hashtext (e.id::text || d.day::text)) % 5)
  ],
  (abs(hashtext (e.id::text)) % 3) = 0,
  m.id,
  'draft'
from
  hr.employees e
  left join hr.employees m on m.id = e.manager_id
  cross join generate_series(
    current_date - 20,
    current_date - 1,
    interval '1 day'
  ) as d (day)
where
  e.employment_status = 'active'
  and e.manager_id is not null
  and extract(
    isodow
    from
      d.day
  ) < 6
  and (abs(hashtext (e.id::text)) % 3) = 0;

update hr.timesheet_entries
set
  status = 'submitted'
where
  work_date < current_date - 2;

update hr.timesheet_entries
set
  status = 'approved'
where
  status = 'submitted'
  and work_date < current_date - 7;

update hr.timesheet_entries
set
  submitted_at = (work_date + 1)::timestamptz + interval '18 hours',
  approved_at = case
    when approved_at is not null then (work_date + 2)::timestamptz + interval '10 hours'
  end,
  updated_at = (work_date + 2)::timestamptz + interval '10 hours';

----------------------------------------------------------------
-- Performance cycles
----------------------------------------------------------------
insert into
  hr.performance_cycles (
    id,
    name,
    status,
    period_start,
    period_end,
    self_assessment_due,
    manager_review_due,
    calibration_on,
    instructions,
    color
  )
values
  (
    '18000000-0000-0000-0000-000000000001',
    'H2 2025 Review',
    'calibration',
    current_date - 400,
    current_date - 220,
    current_date - 210,
    current_date - 200,
    current_date - 190,
    '<p>Look back over the half. Two things that went well, one to work on.</p>',
    '#64748b'
  ),
  (
    '18000000-0000-0000-0000-000000000002',
    'H1 2026 Review',
    'manager_review',
    current_date - 190,
    current_date - 10,
    current_date - 30,
    current_date + 5,
    current_date + 14,
    '<p>Same shape as last time. Bring evidence, not adjectives.</p>',
    '#0f766e'
  );

----------------------------------------------------------------
-- Reviews
--
-- Raised at not_started, then walked: self-assessment, manager
-- review, shared, acknowledged. Sharing without a rating is refused
-- by the trigger, so every shared review below carries one.
----------------------------------------------------------------
insert into
  hr.performance_reviews (
    id,
    cycle_id,
    employee_id,
    reviewer_id,
    self_assessment,
    manager_comment,
    strengths,
    development_areas,
    rating,
    overall_score,
    promotion_recommended
  )
values
  (
    '19000000-0000-0000-0000-000000000001',
    '18000000-0000-0000-0000-000000000001',
