-- Age the review stamps, and close the older cycle.
update hr.performance_reviews r
set
  self_submitted_at = case
    when r.self_submitted_at is not null then (c.self_assessment_due - 3)::timestamptz + interval '16 hours'
  end,
  shared_at = case
    when r.shared_at is not null then (c.manager_review_due - 1)::timestamptz + interval '10 hours'
  end,
  acknowledged_at = case
    when r.acknowledged_at is not null then (c.manager_review_due + 2)::timestamptz + interval '14 hours'
  end,
  updated_at = c.manager_review_due::timestamptz
from
  hr.performance_cycles c
where
  c.id = r.cycle_id;

update hr.performance_cycles
set
  status = 'closed'
where
  id = '18000000-0000-0000-0000-000000000001';

