----------------------------------------------------------------
-- Enrollments — mandatory courses for everyone, electives by
-- interest. enrollment_count, completion_count and average_rating on
-- the course are rollups.
----------------------------------------------------------------
insert into
  hr.training_enrollments (
    course_id,
    employee_id,
    status,
    enrolled_on,
    started_on,
    score,
    rating,
    feedback
  )
select
  c.id,
  e.id,
  v.status::hr.enrollment_status,
  current_date - v.days_ago,
  case
    when v.status <> 'enrolled' then current_date - v.days_ago + 2
  end,
  case
    when v.status in ('completed', 'failed') then 60 + (abs(hashtext (e.id::text || c.id::text)) % 40)
  end,
  case
    when v.status = 'completed' then 3 + (abs(hashtext (e.id::text)) % 3)
  end,
  case
    when v.status = 'completed' then 'Useful, and shorter than I expected.'
  end
from
  hr.employees e
  join hr.training_courses c on (
    c.is_mandatory
    or (abs(hashtext (e.id::text || c.id::text)) % 5) = 0
  )
  cross join lateral (
    select
      case
        when (abs(hashtext (e.id::text || c.id::text)) % 10) < 6 then 'completed'
        when (abs(hashtext (e.id::text || c.id::text)) % 10) < 8 then 'in_progress'
        when (abs(hashtext (e.id::text || c.id::text)) % 10) = 8 then 'enrolled'
        else 'withdrawn'
      end as status,
      30 + (abs(hashtext (e.id::text || c.id::text)) % 250) as days_ago
  ) v
where
  e.employment_status = 'active';

