insert into
  hr.interviews (
    candidate_id,
    interviewer_id,
    kind,
    scheduled_at,
    duration,
    meeting_url,
    location,
    is_completed,
    outcome,
    score,
    feedback
  )
select
  c.id,
  o.hiring_manager_id,
  v.kind::hr.interview_kind,
  (c.applied_on + v.offset_days)::timestamptz + interval '10 hours',
  3600000,
  'https://meet.example.test/' || left(replace(c.id::text, '-', ''), 10),
  'Video call',
  v.done,
  case
    when v.done then v.outcome::hr.interview_outcome
  end,
  case
    when v.done then v.score
  end,
  case
    when v.done then '<p>Structured scorecard completed against the rubric.</p>'
  end
from
  hr.candidates c
  join hr.job_openings o on o.id = c.opening_id
  cross join lateral (
    values
      ('phone_screen', 4, true, 'yes', 4),
      (
        'technical',
        11,
        c.stage in ('interviewing', 'offer', 'hired', 'rejected'),
        'yes',
        4
      ),
      (
        'final',
        18,
        c.stage in ('offer', 'hired'),
        'strong_yes',
        5
      )
  ) as v (kind, offset_days, done, outcome, score)
where
  c.stage <> 'applied';

----------------------------------------------------------------
-- Onboarding
--
-- The master checklist first (employee_id null), then a copy for
-- everyone who has joined in the last ninety days. The trigger turns
-- each offset into a real due date from their start date.
----------------------------------------------------------------
select
  supasheet.apply_template (
    'hr',
    'onboarding_tasks_template',
    'onboarding_tasks'
  );

insert into
  hr.onboarding_tasks (
    employee_id,
    title,
    description,
    category,
    status,
    owner_id,
    offset_days,
    is_blocking,
    sort_order
  )
select
  e.id,
  t.title,
  t.description,
  t.category,
  case
    when e.hire_date + t.offset_days < current_date - 3 then 'done'::hr.onboarding_status
    when e.hire_date + t.offset_days < current_date then 'in_progress'::hr.onboarding_status
    else 'pending'::hr.onboarding_status
  end,
  coalesce(e.manager_id, e.id),
  t.offset_days,
  t.is_blocking,
  t.sort_order
from
  hr.employees e
  cross join hr.onboarding_tasks t
where
  t.employee_id is null
  and e.hire_date >= current_date - 90
  and e.employment_status <> 'terminated';

----------------------------------------------------------------
-- Age the employee history
--
-- Every event above was filed by a trigger during this seed run.
-- Each is moved onto the moment it describes, and attributed to
-- people operations where the seed had no session.
----------------------------------------------------------------
update hr.employee_events ev
set
  occurred_at = case ev.event_type
    when 'hired' then e.hire_date::timestamptz + interval '9 hours'
    when 'terminated' then e.termination_date::timestamptz + interval '17 hours'
    when 'leave_taken' then (e.hire_date + 30)::timestamptz
    else e.hire_date::timestamptz + interval '30 days'
  end,
  actor_id = coalesce(
    ev.actor_id,
    'b73eb03e-fb7a-424d-84ff-18e2791ce0b8'::uuid
  )
from
  hr.employees e
where
  e.id = ev.employee_id;

-- Leave and review events sit on their own dates rather than the
-- employee's start date.
update hr.employee_events ev
set
  occurred_at = r.start_date::timestamptz + interval '9 hours'
from
  hr.leave_requests r
where
  ev.event_type = 'leave_taken'
  and (ev.metadata ->> 'request_id')::uuid = r.id;

update hr.employee_events ev
set
  occurred_at = coalesce(pr.acknowledged_at, pr.shared_at, ev.occurred_at)
from
  hr.performance_reviews pr
where
  ev.event_type = 'review_completed'
  and (ev.metadata ->> 'cycle_id')::uuid = pr.cycle_id
  and pr.employee_id = ev.employee_id;

----------------------------------------------------------------
-- Run the nightly maintenance once, then build the snapshot.
----------------------------------------------------------------
select
  hr.refresh_people_state () as rows_aged;

refresh materialized view hr.headcount_snapshot;
